const startedAt = new Date().toISOString();

function sha256(s) {
  return crypto.createHash("sha256").update(s, "utf8").digest("hex");
}

const b = await chromium.launch({
  executablePath: EXE,
  headless: true,
  ...(process.env.PW_PROXY ? { proxy: { server: process.env.PW_PROXY } } : {}),
