  const hit = page.locator(`text=${title}`).first();
  if (!(await hit.count())) return false;
  await hit.click({ timeout: 5000 }).catch(() => {});
  await page.waitForTimeout(1500);
  return (await page.locator(`text=${title}`).count()) > 0;
}

