const TAG_MAP = {
  view: "div",
  "scroll-view": "div",
  block: null, // 透明
  text: "span",
  image: "img",
  navigator: "div",
  button: "button",
  input: "input",
  textarea: "textarea",
  label: "label",
  "rich-text": "div",
  swiper: "div",
  "swiper-item": "div",
