"use client";

/* ============================================================
 * Obsidian 式力导向关系图谱（Canvas 版）
 *
 * 相比旧 SVG 版的关键升级：
 *   1. 滚轮缩放（以鼠标为中心）+ 空白拖拽平移 + 右下角缩放按钮 + 一键适应
 *   2. 网格分桶斥力（O(n·邻域)）+ alpha 冷却 —— 930+ 节点流畅，
 *      旧版 O(n²)/帧 + 每帧全量重渲是截图里「网格状卡死」的根因
 *   3. 标签随缩放级别显隐（zoom ≥ 0.75 全显，hover 邻居常显）
 *   4. 未解析链接（unresolved）画灰色虚线虚影，与 Obsidian 一致
 *   5. 稳定后停止重绘（CPU 归零），交互/数据变化自动唤醒
 * ============================================================ */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { useAppStore } from "@/lib/store";
import { toast } from "sonner";
import { Link2 } from "lucide-react";
import type { KnowledgeItem } from "@/lib/types";

interface SimNode {
  id: string;
  title: string;
  domain: string;
  degree: number;
  unresolved: boolean;
  x: number;
  y: number;
  vx: number;
  vy: number;
}

const WORLD = 1400; // 初始布局半径参考（世界坐标无边界，可无限平移）

export function GraphView({
  notes,
  onOpen,
  focusId,
}: {
  notes: KnowledgeItem[];
  onOpen: (id: string) => void;
  /** 打开图谱时把镜头居中到这篇笔记(及其邻居),避免用户进来面对空图自己找 */
  focusId?: string | null;
}) {
  const [gQuery, setGQuery] = useState("");
  /* 输入即过滤会让大库每次击键重扫全部正文、并整体重启力导向布局；
   * 停手 250ms 后才应用（输入框本身仍即时回显） */
  const [gQueryApplied, setGQueryApplied] = useState("");
  useEffect(() => {
    const t = setTimeout(() => setGQueryApplied(gQuery), 250);
    return () => clearTimeout(t);
  }, [gQuery]);
  const [gDomain, setGDomain] = useState("all");
  const [showOrphans, setShowOrphans] = useState(true);
  const [panelOpen, setPanelOpen] = useState(false);
  const [rebuilding, setRebuilding] = useState(false);

  const gDomains = useMemo(
    () => Array.from(new Set(notes.map((n) => n.domain.split("/")[0]))).sort(),
    [notes]
  );

  const baseNotes = useMemo(() => {
    const q = gQueryApplied.trim().toLowerCase();
    return notes.filter((n) => {
      if (gDomain !== "all" && n.domain.split("/")[0] !== gDomain) return false;
      if (!q) return true;
      return n.title.toLowerCase().includes(q) || n.body.toLowerCase().includes(q);
    });
  }, [notes, gQueryApplied, gDomain]);

  const orphanIds = useMemo(() => {
    const linked = new Set<string>();
    for (const n of baseNotes) for (const l of n.links) linked.add(l);
    return new Set(baseNotes.filter((n) => n.links.length === 0 && !linked.has(n.id)).map((n) => n.id));
  }, [baseNotes]);

  /* 孤立节点开关真正过滤画布（此前只改了计数文字，勾掉后节点一个不少） */
  const visibleNotes = useMemo(
    () => (showOrphans ? baseNotes : baseNotes.filter((n) => !orphanIds.has(n.id))),
    [baseNotes, orphanIds, showOrphans]
  );

  const edgeList = useMemo(() => {
    const idSet = new Set(visibleNotes.map((n) => n.id));
    const seen = new Set<string>();
    const out: { a: string; b: string }[] = [];
    for (const n of visibleNotes) {
      for (const l of n.links) {
        if (!idSet.has(l) || l === n.id) continue;
        const key = n.id < l ? `${n.id}|${l}` : `${l}|${n.id}`;
        if (seen.has(key)) continue;
        seen.add(key);
        out.push({ a: n.id, b: l });
      }
    }
    return out;
  }, [visibleNotes]);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wrapRef = useRef<HTMLDivElement>(null);
  const nodesRef = useRef<SimNode[]>([]);
  const edgesRef = useRef<{ a: string; b: string }[]>([]);
  const camRef = useRef({ x: 0, y: 0, zoom: 1 }); // 相机：世界坐标偏移 + 缩放
  const hoverRef = useRef<string | null>(null);
  const dragNodeRef = useRef<string | null>(null);
  const panRef = useRef<{ sx: number; sy: number; cx: number; cy: number } | null>(null);
  const downPtRef = useRef<{ x: number; y: number } | null>(null);
  const movedRef = useRef(false); // 拖节点/平移后松手的 click 不是点选（否则拖完必误开笔记）
  const alphaRef = useRef(1);
  const dirtyRef = useRef(true);
  const sizeRef = useRef({ w: 920, h: 560 });
  const countsRef = useRef({ nodes: 0, edges: 0 });
  /* 画布底色跟随时段主题：全站底色由 <html data-period> 上的 --color-bg 决定
   * （globals.css:454-458，app-shell.tsx 每 10 分钟 applyPeriodTheme），写死
   * #fcfcfd 会让近 100vh 的图谱块在早读/晚间与周围页面出现可见色差。
   * 按 data-period 值缓存，避免 render 每帧 getComputedStyle 触发样式重算。 */
  const themeBgRef = useRef<{ key: string; color: string }>({ key: "\u0000", color: "#fcfcfd" });
  const themeBg = () => {
    const key = document.documentElement.getAttribute("data-period") ?? "";
    if (themeBgRef.current.key !== key) {
      const v = getComputedStyle(document.documentElement).getPropertyValue("--color-bg").trim();
      themeBgRef.current = { key, color: v || "#fcfcfd" };
    }
    return themeBgRef.current.color;
  };
  /* v17：HUD 展示值（节点/边计数、缩放百分比）从"渲染期读 ref"迁到 state。
   * React Compiler 禁止渲染读 ref——此前 zoom% 标签读 camRef，滚轮缩放时不会重渲染，
   * 显示是坏的（forceRender 黑客只覆盖数据变化，覆盖不到相机变化）。
   * 规则同时禁止 effect 同步 setState：统一走 rAF 一拍后同步。 */
  const [viewStats, setViewStats] = useState({ zoom: 100, nodes: 0, edges: 0 });
  const syncStats = useCallback(() => {
    requestAnimationFrame(() =>
      setViewStats({
        zoom: Math.round(camRef.current.zoom * 100),
        nodes: countsRef.current.nodes,
        edges: countsRef.current.edges,
      })
    );
  }, []);

  /* ---- 数据 → 仿真节点（保留旧位置，新增节点螺旋散布） ---- */
  useEffect(() => {
    edgesRef.current = edgeList;
    const prev = new Map(nodesRef.current.map((n) => [n.id, n]));
    const degree = new Map<string, number>();
    for (const e of edgeList) {
      degree.set(e.a, (degree.get(e.a) ?? 0) + 1);
      degree.set(e.b, (degree.get(e.b) ?? 0) + 1);
    }
    let i = 0;
    nodesRef.current = visibleNotes.map((n) => {
      const old = prev.get(n.id);
      i += 1;
      const angle = i * 2.399963; // 黄金角螺旋，初始散布均匀
      const rad = 30 + Math.sqrt(i) * 14;
      return {
        id: n.id,
        title: n.title,
        domain: n.domain,
        unresolved: Boolean(n.unresolved),
        degree: degree.get(n.id) ?? 0,
        x: old?.x ?? WORLD / 2 + Math.cos(angle) * rad,
        y: old?.y ?? WORLD / 2 + Math.sin(angle) * rad,
        vx: 0,
        vy: 0,
      };
    });
    countsRef.current = { nodes: nodesRef.current.length, edges: edgeList.length };
    /* 仅当节点集合真的变了才整体重启布局；纯过滤（集合相同）只温和唤醒重绘，
     * 避免连续输入时把 CPU 全耗在无意义的重排上 */
    const setChanged =
      nodesRef.current.length !== prev.size || nodesRef.current.some((n) => !prev.has(n.id));
    alphaRef.current = setChanged ? 1 : Math.max(alphaRef.current, 0.15);
    dirtyRef.current = true;
    syncStats();
  }, [visibleNotes, edgeList, syncStats]);

  /* ---- 主循环：物理（网格分桶）+ 按需渲染 ---- */
  useEffect(() => {
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d")!;
    let raf = 0;
    let running = true;

    const byId = () => {
      const m = new Map<string, SimNode>();
      for (const n of nodesRef.current) m.set(n.id, n);
      return m;
    };

    const physics = () => {
      const nodes = nodesRef.current;
      const edges = edgesRef.current;
      const alpha = alphaRef.current;
      /* alpha 冷却必须在空图早退之前——否则 0 节点（新用户空库 /
       * 搜索过滤零命中）时 needsPhysics = alpha > 0.02 永真，
       * rAF 主循环 60fps 永不停歇，与文件头第 5 点「稳定后停止重绘」矛盾 */
      alphaRef.current = alpha * 0.99;
      if (nodes.length === 0) return;

      /* 斥力：网格分桶，只和邻近格子里的节点相互作用 */
      const CELL = 130;
      const grid = new Map<string, SimNode[]>();
      for (const n of nodes) {
        const key = `${Math.floor(n.x / CELL)},${Math.floor(n.y / CELL)}`;
        const bucket = grid.get(key);
        if (bucket) bucket.push(n);
        else grid.set(key, [n]);
      }
      const REP = 1400 * alpha;
      for (const n of nodes) {
        const cx = Math.floor(n.x / CELL);
        const cy = Math.floor(n.y / CELL);
        for (let gx = cx - 1; gx <= cx + 1; gx++) {
          for (let gy = cy - 1; gy <= cy + 1; gy++) {
            const bucket = grid.get(`${gx},${gy}`);
            if (!bucket) continue;
            for (const o of bucket) {
              if (o.id <= n.id) continue;
              let dx = n.x - o.x, dy = n.y - o.y;
              let d2 = dx * dx + dy * dy;
              if (d2 < 1) { dx = Math.random() - 0.5; dy = Math.random() - 0.5; d2 = 1; }
              if (d2 > CELL * CELL * 2) continue;
              const d = Math.sqrt(d2);
              const f = Math.min(REP / d2, 3) / d;
              const fx = dx * f, fy = dy * f;
              n.vx += fx; n.vy += fy;
              o.vx -= fx; o.vy -= fy;
            }
          }
        }
      }

      /* 弹簧：相连节点靠拢 */
      const map = byId();
      for (const e of edges) {
        const a = map.get(e.a), b = map.get(e.b);
        if (!a || !b) continue;
        const dx = b.x - a.x, dy = b.y - a.y;
        const d = Math.max(1, Math.sqrt(dx * dx + dy * dy));
        const rest = 95;
        const f = ((d - rest) / d) * 0.055 * alpha;
        const fx = dx * f, fy = dy * f;
        a.vx += fx; a.vy += fy;
        b.vx -= fx; b.vy -= fy;
      }

      /* 向心 + 阻尼 + 积分（无边界夹持——世界无限，靠缩放看全貌） */
      const cx = WORLD / 2, cy = WORLD / 2;
      for (const n of nodes) {
        if (dragNodeRef.current === n.id) { n.vx = 0; n.vy = 0; continue; }
        n.vx += (cx - n.x) * 0.002 * alpha;
        n.vy += (cy - n.y) * 0.002 * alpha;
        n.vx *= 0.85; n.vy *= 0.85;
        n.x += Math.max(-9, Math.min(9, n.vx));
        n.y += Math.max(-9, Math.min(9, n.vy));
      }
    };

    const render = () => {
      const { w, h } = sizeRef.current;
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      /* canvas.width/height 是 unsigned long：赋值小数会被截断存整。
       * 若直接拿未取整的 w * dpr 做守卫（getBoundingClientRect 与
       * calc(100vh - 170px) 都可能带小数，分数 DPR 更会放大），
       * 下一帧比较「截断后的整数 !== 未取整的小数」恒为真，
       * 动画/平移/滚轮期间每帧都重设 width/height（清空位图 + 可能重分配后备缓冲）。
       * 目标尺寸先取整，守卫与赋值共用同一个整数即稳定。 */
      const bw = Math.round(w * dpr);
      const bh = Math.round(h * dpr);
      if (canvas.width !== bw || canvas.height !== bh) {
        canvas.width = bw;
        canvas.height = bh;
      }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = themeBg();
      ctx.fillRect(0, 0, w, h);

      const cam = camRef.current;
      const zoom = cam.zoom;
      const toScreen = (x: number, y: number): [number, number] => [
        (x - cam.x) * zoom + w / 2,
        (y - cam.y) * zoom + h / 2,
      ];

      const hover = hoverRef.current;
      let neighborSet: Set<string> | null = null;
      if (hover) {
        neighborSet = new Set([hover]);
        for (const e of edgesRef.current) {
          if (e.a === hover) neighborSet.add(e.b);
          if (e.b === hover) neighborSet.add(e.a);
        }
      }

      /* 边 */
      const map = new Map(nodesRef.current.map((n) => [n.id, n]));
      for (const e of edgesRef.current) {
        const a = map.get(e.a), b = map.get(e.b);
        if (!a || !b) continue;
        const active = !neighborSet || (neighborSet.has(e.a) && neighborSet.has(e.b));
        ctx.beginPath();
        ctx.moveTo(...toScreen(a.x, a.y));
        ctx.lineTo(...toScreen(b.x, b.y));
        ctx.strokeStyle = active ? (hover ? "#8a8a92" : "#c9c9cf") : "#e4e4e9";
        ctx.lineWidth = (active ? 1.3 : 0.8) * Math.max(0.5, zoom);
        ctx.stroke();
      }

      /* 节点 */
      const showLabels = zoom >= 0.75 || nodesRef.current.length < 80;
      for (const n of nodesRef.current) {
        const active = !neighborSet || neighborSet.has(n.id);
        const [sx, sy] = toScreen(n.x, n.y);
        if (sx < -40 || sy < -40 || sx > w + 40 || sy > h + 40) continue; // 视口裁剪
        const r = (n.unresolved ? 4.5 : 6 + Math.min(13, Math.sqrt(n.degree) * 2.6)) * zoom;
        const x = sx, y = sy;
        ctx.globalAlpha = active ? 1 : 0.15;
        if (n.unresolved) {
          ctx.beginPath();
          ctx.arc(x, y, r, 0, Math.PI * 2);
          ctx.strokeStyle = "#b6b6bd";
          ctx.setLineDash([2.5, 2.5]);
          ctx.lineWidth = 1.2 * Math.max(0.5, zoom);
          ctx.stroke();
          ctx.setLineDash([]);
        } else {
          /* Obsidian 单色系：连接越多越黑，无彩色 */
          ctx.beginPath();
          ctx.arc(x, y, r, 0, Math.PI * 2);
          const t = Math.min(1, n.degree / 8); // 0 孤立 → 1枢纽
          ctx.fillStyle = t > 0.5 ? "#232326" : t > 0.15 ? "#55555c" : "#8f8f96";
          ctx.fill();
          if (hover === n.id) {
            ctx.strokeStyle = "#1d1d1f";
            ctx.lineWidth = 1.6;
            ctx.stroke();
          }
        }
        /* 标签：缩放足够大，或 hover/邻居时 */
        if (showLabels || (neighborSet && neighborSet.has(n.id))) {
          const label = n.title.length > 14 ? n.title.slice(0, 14) + "…" : n.title;
          ctx.font = `${11 * Math.max(0.85, zoom)}px ui-sans-serif, system-ui, sans-serif`;
          ctx.textAlign = "center";
          ctx.fillStyle = hover === n.id ? "#1d1d1f" : active ? "#77777d" : "#c4c4ca";
          ctx.fillText(label, x, y + r + 12 * Math.max(0.85, zoom));
        }
        ctx.globalAlpha = 1;
      }
    };

    const loop = () => {
      if (!running) return;
      const needsPhysics = alphaRef.current > 0.02 || dragNodeRef.current;
      if (needsPhysics) {
        physics();
        physics(); // 每帧两步，收敛更快
        dirtyRef.current = true;
      }
      if (dirtyRef.current) {
        dirtyRef.current = false;
        render();
      }
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => { running = false; cancelAnimationFrame(raf); };
  }, []);

  /* ---- 尺寸自适应 ---- */
  useEffect(() => {
    const wrap = wrapRef.current!;
    const ro = new ResizeObserver(() => {
      const canvas = canvasRef.current;
      if (!wrapRef.current || !canvas) return; // 卸载竞态：节点已移除时不再读 style
      const r = wrapRef.current.getBoundingClientRect();
      sizeRef.current = { w: r.width, h: r.height };
      canvas.style.width = `${r.width}px`;
      canvas.style.height = `${r.height}px`;
      dirtyRef.current = true;
    });
    ro.observe(wrap);
    return () => ro.disconnect();
  }, []);

  /* 没有焦点笔记时(如从侧栏直接进图谱),自动 fitView 让全图入视野,避免"打开是空的" */
  useEffect(() => {
    if (focusId) return;
    const t = setTimeout(() => {
      fitView();
      dirtyRef.current = true;
    }, 700);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [focusId, notes.length]);

  /* 打开图谱时把镜头居中到 focusId 笔记(等物理布局稳定后),用户一眼看到它的关系网 */
  useEffect(() => {
    if (!focusId) return;
    let tries = 0;
    const iv = setInterval(() => {
      const n = nodesRef.current.find((x) => x.id === focusId);
      if (n) {
        camRef.current = { x: n.x, y: n.y, zoom: 1.35 };
        syncStats();
        dirtyRef.current = true;
        if (++tries > 2) clearInterval(iv);
      } else if (++tries > 20) {
        clearInterval(iv);
      }
    }, 120);
    return () => clearInterval(iv);
  }, [focusId]);

  /* 滚轮缩放要阻止页面滚动，但 React 的 onWheel 是 passive 的，preventDefault 会告警；
   * 故用原生非 passive 监听单独拦截默认滚动，onWheel 只算缩放数学。 */
  useEffect(() => {
    const cv = canvasRef.current;
    if (!cv) return;
    const block = (e: WheelEvent) => e.preventDefault();
    cv.addEventListener("wheel", block, { passive: false });
    return () => cv.removeEventListener("wheel", block);
  }, []);

  /* ---- 相机与交互 ---- */
  const screenToWorld = (sx: number, sy: number) => {
    const { w, h } = sizeRef.current;
    const cam = camRef.current;
    return { x: (sx - w / 2) / cam.zoom + cam.x, y: (sy - h / 2) / cam.zoom + cam.y };
  };

  const pickNode = (sx: number, sy: number): SimNode | null => {
    const { x, y } = screenToWorld(sx, sy);
    const pad = 8 / camRef.current.zoom;
    for (let i = nodesRef.current.length - 1; i >= 0; i--) {
      const n = nodesRef.current[i];
      const r = n.unresolved ? 4.5 : 6 + Math.min(13, Math.sqrt(n.degree) * 2.6);
      const dx = n.x - x, dy = n.y - y;
      if (dx * dx + dy * dy <= (r + pad) * (r + pad)) return n;
    }
    return null;
  };

  const onPointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const sx = e.clientX - rect.left, sy = e.clientY - rect.top;
    downPtRef.current = { x: sx, y: sy };
    movedRef.current = false;
    const node = pickNode(sx, sy);
    if (node) {
      dragNodeRef.current = node.id;
      alphaRef.current = Math.max(alphaRef.current, 0.35);
    } else {
      panRef.current = { sx, sy, cx: camRef.current.x, cy: camRef.current.y };
      e.currentTarget.setPointerCapture(e.pointerId);
    }
  };

  const onPointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const sx = e.clientX - rect.left, sy = e.clientY - rect.top;

    const down = downPtRef.current;
    if (down && (Math.abs(sx - down.x) > 3 || Math.abs(sy - down.y) > 3)) movedRef.current = true;

    if (panRef.current) {
      camRef.current.x = panRef.current.cx - (sx - panRef.current.sx) / camRef.current.zoom;
      camRef.current.y = panRef.current.cy - (sy - panRef.current.sy) / camRef.current.zoom;
      dirtyRef.current = true;
      return;
    }
    if (dragNodeRef.current) {
      const n = nodesRef.current.find((nn) => nn.id === dragNodeRef.current);
      if (n) {
        const { x, y } = screenToWorld(sx, sy);
        n.x = x; n.y = y;
        dirtyRef.current = true;
      }
      return;
    }
    const node = pickNode(sx, sy);
    if (node?.id !== hoverRef.current) {
      hoverRef.current = node?.id ?? null;
      e.currentTarget.style.cursor = node ? "grab" : "default";
      dirtyRef.current = true;
    }
  };

  const onPointerUp = () => {
    dragNodeRef.current = null;
    panRef.current = null;
    downPtRef.current = null;
    alphaRef.current = Math.max(alphaRef.current, 0.12);
  };

  const onWheel = (e: React.WheelEvent<HTMLCanvasElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const sx = e.clientX - rect.left, sy = e.clientY - rect.top;
    const cam = camRef.current;
    const world = screenToWorld(sx, sy);
    const factor = e.deltaY < 0 ? 1.15 : 1 / 1.15;
    cam.zoom = Math.max(0.06, Math.min(5, cam.zoom * factor));
    /* 保证鼠标下的世界点不动 */
    cam.x = world.x - (sx - sizeRef.current.w / 2) / cam.zoom;
    cam.y = world.y - (sy - sizeRef.current.h / 2) / cam.zoom;
    dirtyRef.current = true;
    syncStats();
  };

  const zoomBy = (factor: number) => {
    const cam = camRef.current;
    cam.zoom = Math.max(0.06, Math.min(5, cam.zoom * factor));
    dirtyRef.current = true;
    syncStats();
  };

  function fitView() {
    const nodes = nodesRef.current;
    if (nodes.length === 0) return;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const n of nodes) {
      minX = Math.min(minX, n.x); minY = Math.min(minY, n.y);
      maxX = Math.max(maxX, n.x); maxY = Math.max(maxY, n.y);
    }
    const { w, h } = sizeRef.current;
    const pad = 60;
    camRef.current.zoom = Math.max(0.06, Math.min(2.5,
      Math.min((w - pad * 2) / Math.max(1, maxX - minX), (h - pad * 2) / Math.max(1, maxY - minY))
    ));
    camRef.current.x = (minX + maxX) / 2;
    camRef.current.y = (minY + maxY) / 2;
    dirtyRef.current = true;
    syncStats();
  }

  const onClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    /* 拖拽节点/平移画布松手也会派发 click：位移超门槛就不当作点选 */
    if (movedRef.current) {
      movedRef.current = false;
      return;
    }
    const rect = e.currentTarget.getBoundingClientRect();
    const node = pickNode(e.clientX - rect.left, e.clientY - rect.top);
    if (node) onOpen(node.id);
  };

  const rebuild = async () => {
    if (rebuilding) return;
    if (!confirm("扫描全部笔记正文，重建 [[双链]] 关系？\n\n解析不到目标标题的链接会建成「未解析链接」占位笔记（Obsidian 同款行为）；已有人工/AI 建立的链接保留。")) return;
    setRebuilding(true);
    /* rebuildLinks 是同步重活：先让一帧把「重建中…」和 disabled 画出来，
     * 否则 true/false 同批合并，loading 是死状态、防重复点击失效 */
    await new Promise((r) => setTimeout(r, 30));
    try {
      const r = useAppStore.getState().rebuildLinks();
      toast.success(`关系链重建完成：更新 ${r.touched} 篇，新建未解析占位 ${r.placeholders} 篇`);
      alphaRef.current = 1;
      dirtyRef.current = true;
    } catch {
      toast.error("重建失败，稍后再试");
    } finally {
      setRebuilding(false);
    }
  };

  const shownCount = showOrphans ? viewStats.nodes : visibleNotes.filter((n) => !orphanIds.has(n.id)).length;

  return (
    <div className="relative" ref={wrapRef}>
      {/* Obsidian 式右上角控制面板 */}
      <div className="absolute right-3 top-3 z-10 w-56 rounded-xl border border-border bg-white/95 p-2.5 shadow-sm backdrop-blur">
        <div className="mb-1.5 flex items-center justify-between">
          <p className="text-[10.5px] font-semibold uppercase tracking-wider text-ink-dim/70">图谱过滤</p>
          <button
            onClick={() => setPanelOpen((v) => !v)}
            aria-expanded={panelOpen}
            className="text-[10.5px] text-accent hover:underline cursor-pointer"
          >
            {panelOpen ? "收起" : "展开"}
          </button>
        </div>
        {panelOpen ? (
          <div className="space-y-2">
            <input
              className="w-full rounded-lg border border-border bg-white px-2.5 py-1.5 text-[12px] outline-none focus:border-accent/50"
              placeholder="搜索笔记标题/正文…"
              value={gQuery}
              onChange={(e) => setGQuery(e.target.value)}
            />
            <div className="flex flex-wrap gap-1">
              <button
                onClick={() => setGDomain("all")}
                className={cn(
                  "rounded-full border px-2 py-0.5 text-[10.5px] cursor-pointer",
                  gDomain === "all"
                    ? "border-accent/40 bg-accent/[0.1] font-semibold text-accent"
                    : "border-border bg-white text-ink-dim hover:text-ink"
                )}
              >
                全部目录
              </button>
              {gDomains.map((d) => (
                <button
                  key={d}
                  onClick={() => setGDomain(gDomain === d ? "all" : d)}
                  className={cn(
                    "max-w-full truncate rounded-full border px-2 py-0.5 text-[10.5px] cursor-pointer",
                    gDomain === d
                      ? "border-accent/40 bg-accent/[0.1] font-semibold text-accent"
                      : "border-border bg-white text-ink-dim hover:text-ink"
                  )}
                >
                  {d}
                </button>
              ))}
            </div>
            <label className="flex cursor-pointer items-center gap-1.5 text-[12px] text-ink-dim">
              <input
                type="checkbox"
                checked={showOrphans}
                onChange={(e) => setShowOrphans(e.target.checked)}
                className="size-3 accent-accent"
              />
              显示孤立节点（无连接）
            </label>
            <button
              onClick={rebuild}
              disabled={rebuilding}
              className="flex w-full items-center justify-center gap-1.5 rounded-lg border border-border bg-white px-2 py-1.5 text-[11.5px] text-ink-dim transition hover:border-accent/40 hover:text-accent cursor-pointer disabled:opacity-50"
              title="扫描全部笔记正文里的 [[双链]]，重建导入时丢失的关系；解析不到的目标建成灰色占位笔记"
            >
              <Link2 className="size-3.5" />
              {rebuilding ? "重建中…" : "重建关系链（修复导入丢失）"}
            </button>
          </div>
        ) : (
          <p className="text-[10.5px] text-ink-dim/70">
            {shownCount} 节点 · {viewStats.edges} 连接
          </p>
        )}
      </div>

      {/* 右下角缩放控件（Obsidian 同款） */}
      <div className="absolute bottom-3 right-3 z-10 flex overflow-hidden rounded-lg border border-border bg-white/95 shadow-sm backdrop-blur">
        <button onClick={() => zoomBy(1 / 1.3)} title="缩小" aria-label="缩小" className="px-2.5 py-1.5 text-sm text-ink-dim hover:bg-black/[0.04] hover:text-ink cursor-pointer">−</button>
        <button onClick={() => { camRef.current.zoom = 1; dirtyRef.current = true; syncStats(); }} title="重置缩放" aria-label={`重置缩放为 100%，当前 ${viewStats.zoom}%`} className="border-x border-border px-2.5 py-1.5 text-[11px] tabular text-ink-dim hover:bg-black/[0.04] hover:text-ink cursor-pointer">
          {viewStats.zoom}%
        </button>
        <button onClick={() => zoomBy(1.3)} title="放大" aria-label="放大" className="px-2.5 py-1.5 text-sm text-ink-dim hover:bg-black/[0.04] hover:text-ink cursor-pointer">+</button>
        <button onClick={fitView} title="适应全图" aria-label="适应全图" className="border-l border-border px-2.5 py-1.5 text-[11px] text-ink-dim hover:bg-black/[0.04] hover:text-ink cursor-pointer">适应</button>
      </div>

      <canvas
        ref={canvasRef}
        role="img"
        aria-label="知识图谱"
        className="block w-full cursor-default touch-none rounded-2xl border border-border bg-[var(--color-bg)]"
        style={{ height: "calc(100vh - 170px)", minHeight: 480 }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerLeave={() => { hoverRef.current = null; onPointerUp(); }}
        onClick={onClick}
        onWheel={onWheel}
        onDoubleClick={fitView}
      />
      {visibleNotes.length === 0 && (
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
          <p className="text-sm text-ink-dim/60">
            {notes.length === 0 ? "笔记还不够多——先积累几条，图谱会长出来" : "没有匹配的笔记"}
          </p>
        </div>
      )}
    </div>
  );
}

"use client";

/* ============================================================
 * NoteWorkspace — 第二大脑的 Obsidian 式工作台
 * 左栏：搜索 / 标签筛选 / 笔记列表 / 新建
 * 中栏：标题 + 工具栏 + [[双链]] 自动补全的编辑器 / 预览（点击双链跳转或建新笔记）
 * 右栏：反向链接 · 出链 · 大纲 · 标签（Obsidian 右侧面板四件套）
 * 全局命令面板（⌘K，cmdk.tsx）负责任意跳转；自动保存（改动即写入，无需手动保存）
 * ============================================================ */

import { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { Button, Empty } from "@/components/ui";
import { WikiMarkdown } from "@/components/brain/wiki-markdown";
import { fileToMarkdown, docTitleFromFilename } from "@/lib/doc-import";
import { useAppStore } from "@/lib/store";
import { cn } from "@/lib/utils";
import type { KnowledgeItem } from "@/lib/types";
import { toast } from "sonner";
import {
  ArrowDownUp, Bold, Braces, ChevronRight, Eye, FileText, FolderPlus, Heading2, Heading3,
  PanelRight,
  Link2, List, ListOrdered, Minus, MoreVertical, Pencil, Plus, Quote, RefreshCcw, Search, Sparkles, Tag,
  Trash2, Type, Upload, X, Zap,
} from "lucide-react";

type RightTab = "backlinks" | "outgoing" | "outline" | "tags";

/** 笔记来源的读法（E3：来源要能看懂，不是枚举值直出） */
const SOURCE_LABELS: Record<string, string> = {
  learn: "学习产出",
  read: "阅读产出",
  council: "圆桌/人生伙伴",
  manual: "手动记录",
  obsidian: "Obsidian 导入",
};

/* ---- 小工具 ---- */

function normTitle(t: string) {
  return t.trim().toLowerCase();
}

/** 大纲：解析正文 1-3 级标题 */
function outlineOf(body: string): { level: number; text: string }[] {
  const out: { level: number; text: string }[] = [];
  for (const line of body.split(/\r?\n/)) {
    const m = line.match(/^(#{1,3})\s+(.+?)\s*#*$/);
    if (m && m[2].trim()) out.push({ level: m[1].length, text: m[2].trim() });
  }
  return out;
}

/** 行内 #标签；配合 tags 字段一起展示。
 *  标题行的行首 #（## 二级）不会被误当标签：捕获组已排除 # 与空白，去掉前导空白后
 *  首字符必然是 #，因此「1-6 个 # + 空白」永远不会命中——无需（也无法）再做一次
 *  「标题行排除」。标题行里另写的 #标签（如「## 项目 #重要」）照常计入，与 Obsidian 一致。 */
function inlineTags(body: string): string[] {
  const out = new Set<string>();
  const re = /(?:^|\s)#([^\s#`~!@#$%^&*()=+{\}[\]|\\:;"'<>,.?/，。！？：（）【】]{2,24})/gm;
  let m: RegExpExecArray | null;
  while ((m = re.exec(body))) {
    const t = m[1].replace(/[.,;:!?，。：；！？]+$/, "");
    if (t && !/^\d+$/.test(t)) out.add(t);
  }
  return [...out];
}

const TAGS_OF = (k: KnowledgeItem) => [...new Set([...(k.tags ?? []), ...inlineTags(k.body)])];

/* 把正文切成"块"（空行分隔；代码围栏内部不拆），供块级实时预览编辑 */
function splitBlocks(body: string): string[] {
  const lines = body.split("\n");
  const blocks: string[] = [];
  let cur: string[] = [];
  let inFence = false;
  const flush = () => {
    if (cur.length) {
      blocks.push(cur.join("\n"));
      cur = [];
    }
  };
  for (const ln of lines) {
    if (/^```/.test(ln.trim())) {
      inFence = !inFence;
      cur.push(ln);
      continue;
    }
    if (!inFence && ln.trim() === "") {
      flush();
      continue;
    }
    cur.push(ln);
  }
  flush();
  return blocks;
}

/* 把「未提交草稿」rebase 到 currentBody 上并返回应写回的正文（null = 无需提交）。
 * 段级编辑只替换目标段落，不再用编辑开始时的 blocks 快照整体覆写正文——否则编辑期间
 * 由别处（AI 追加摘要 / 整篇润色）落库的改动会被 join 出来的旧快照静默抹掉。 */
function rebaseDraft(
  pending:
    | { mode: "whole"; text: string }
    | { mode: "block"; index: number; text: string; blocks: string[] },
  currentBody: string
): string | null {
  if (pending.mode === "whole") return pending.text !== currentBody ? pending.text : null;
  const orig = pending.blocks[pending.index];
  if (pending.text === orig) return null; // 本段没改：不写回，免得白白覆盖别处改动
  const cur = splitBlocks(currentBody);
  /* 优先按原下标（并发改动多为追加，下标仍对齐）；下标处已不是原段落时再按内容找 */
  const at = cur[pending.index] === orig ? pending.index : cur.indexOf(orig);
  if (at >= 0) {
    cur[at] = pending.text;
    return cur.join("\n\n");
  }
  /* 原段落已被别处改写/删除（如整篇 AI 润色）：不覆写整篇，把这次编辑追加为独立段落，
     宁可多一段也不静默丢掉用户刚敲的内容。 */
  return [...cur, pending.text].join("\n\n");
}

/* Obsidian 式实时预览编辑：整篇默认渲染成排版文档；点哪一段,只有那一段进入可编辑(显示原文),
 * 其余段落保持渲染、纹丝不动。不懂 MD 的人也能直接改。提交只替换被编辑的那一块。 */
function LiveBlocks({
  body,
  notes,
  onCommit,
  onOpen,
  onCreate,
  onRewrite,
}: {
  body: string;
  notes: KnowledgeItem[];
  onCommit: (next: string) => void;
  onOpen: (id: string) => void;
  onCreate: (title: string) => void;
  onRewrite?: (t: string) => Promise<string>;
}) {
  const blocks = useMemo(() => splitBlocks(body), [body]);
  const [active, setActive] = useState<number | null>(null);
  const [text, setText] = useState("");
  /* 块级 AI 改写：旧实现既无门也无失败反馈——可以连点发起并发调用，返回后 setText
   * 覆盖用户等待期间敲的内容，失败还静默吞掉（同文件其它 AI 按钮都有门）。
   * 三处都补上了：按钮 disabled 防连点、catch 出 toast、返回期间 textarea readOnly
   * 关掉「等待中继续敲字被 setText 覆盖」的丢失窗口。 */
  const [rewriting, setRewriting] = useState(false);

  /* 尚未提交的草稿。空笔记（blocks=[]）走整篇 textarea 分支，active 恒为 null——
   * 旧实现的 commit() 首行 `if (active == null) return` 让这条默认路径的正文永远不落库，
   * 切到另一篇笔记时组件卸载、局部 state 销毁，用户输入静默丢失。 */
  const pendingRef = useRef<
    | { mode: "whole"; text: string }
    | { mode: "block"; index: number; text: string; blocks: string[] }
    | null
  >(null);
  /* 卸载兜底必须用最新回调；onCommit 闭包绑定的是当前这篇笔记的 id，切走时不会写错对象 */
  const commitRef = useRef(onCommit);
  useEffect(() => {
    commitRef.current = onCommit;
  });
  /* 最新正文镜像：卸载兜底 effect 是空依赖闭包，读不到最新的 body prop——没有它 rebase
   * 只能拿首帧正文，等于又回到「用旧正文兜底」。 */
  const bodyRef = useRef(body);
  useEffect(() => {
    bodyRef.current = body;
  });

  const commit = () => {
    const pending = pendingRef.current;
    pendingRef.current = null;
    if (pending) {
      /* rebase 到此刻的正文：段级编辑只替换本段，不再整体覆写、丢掉编辑期间的 AI 写入 */
      const next = rebaseDraft(pending, body);
      if (next != null) onCommit(next);
    }
    setActive(null);
  };

  /* 兜底：失焦没触发（键盘/程序化跳转、直接切笔记）时也把草稿写回去 */
  useEffect(
    () => () => {
      const pending = pendingRef.current;
      pendingRef.current = null;
      if (!pending) return;
      if (pending.mode === "whole") {
        commitRef.current(pending.text);
      } else {
        /* 同样 rebase 到最新正文（bodyRef），避免卸载时用旧快照覆写 */
        const next = rebaseDraft(pending, bodyRef.current);
        if (next != null) commitRef.current(next);
      }
    },
    []
  );

  const open = (i: number) => {
    // 先落上一段未提交的改动，再切换编辑目标（防止程序化跳转绕过 blur）
    if (pendingRef.current) commit();
    setActive(i);
    setText(blocks[i] ?? "");
    pendingRef.current = null;
  };

  return (
    <div className="min-h-full px-3 py-3">
      {blocks.length === 0 ? (
        <textarea
          autoFocus
          className="min-h-[40vh] w-full resize-none bg-transparent px-2 font-mono text-[13px] leading-relaxed text-ink outline-none"
          value={text}
          placeholder="像聊天一样写就行——点别处自动排版。输入 [[ 可链接其他笔记…"
          onChange={(e) => {
            setText(e.target.value);
            pendingRef.current = { mode: "whole", text: e.target.value };
          }}
          onBlur={commit}
        />
      ) : (
        blocks.map((b, i) =>
          active === i ? (
            <div key={i}>
              {onRewrite && (
                <div className="mb-1 flex justify-end">
                  <button
                    onMouseDown={(e) => e.preventDefault()}
                    disabled={rewriting}
                    onClick={async () => {
                      setRewriting(true);
                      try {
                        const rewritten = await onRewrite(text);
                        setText(rewritten);
                        // 改写结果也是未提交草稿：否则切走时会被当成"没改过"
                        pendingRef.current = { mode: "block", index: i, text: rewritten, blocks };
                      } catch (e) {
                        toast.error(e instanceof Error ? e.message : "AI 改写失败，原文未改动");
                      } finally {
                        setRewriting(false);
                      }
                    }}
                    className="rounded-md px-1.5 py-0.5 text-[10.5px] text-accent transition hover:bg-accent/[0.08] cursor-pointer disabled:opacity-50"
                    title="AI 改写这一段（不改原意）"
                  >
                    {rewriting ? "改写中…" : "✨ AI 改写这段"}
                  </button>
                </div>
              )}
              <textarea
              autoFocus
              rows={Math.max(2, text.split("\n").length + 1)}
              className="my-1 w-full resize-none rounded-lg border border-accent/40 bg-white px-3 py-2 font-mono text-[13px] leading-relaxed text-ink outline-none"
              value={text}
              /* 改写期间只读：否则用户在最长 45s 的等待里继续敲字，onRewrite 返回后的
                 setText(rewritten) 会把这段输入连同 pendingRef 一起静默覆盖掉。
                 readOnly 不移除焦点、不触发 blur，专注状态与已提交草稿都不受影响。 */
              readOnly={rewriting}
              onChange={(e) => {
                setText(e.target.value);
                pendingRef.current = { mode: "block", index: i, text: e.target.value, blocks };
              }}
              onBlur={commit}
              onKeyDown={(e) => {
                if (e.key === "Escape") commit();
              }}
              />
            </div>
          ) : (
            <div
              key={i}
              role="button"
              tabIndex={0}
              onClick={() => open(i)}
              onKeyDown={(e) => {
                /* 键盘也能进块编辑；内部链接按钮的回车不在这里截胡 */
                if (e.target !== e.currentTarget) return;
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  open(i);
                }
              }}
              title="点击编辑这一段（其余保持排版）"
              className="prose-mentora cursor-text rounded-lg px-3 py-1.5 transition hover:bg-black/[0.035]"
            >
              <WikiMarkdown body={b} notes={notes} onOpen={onOpen} onCreate={onCreate} />
            </div>
          )
        )
      )}
    </div>
  );
}

/* Obsidian 式搜索命中上下文：截取首个命中处前后若干字符并压平空白 */
function matchSnippet(body: string, q: string): string | null {
  const idx = body.toLowerCase().indexOf(q);
  if (idx === -1) return null;
  const start = Math.max(0, idx - 18);
  const end = Math.min(body.length, idx + q.length + 42);
  const raw = body.slice(start, end).replace(/\s+/g, " ").trim();
  return `${start > 0 ? "…" : ""}${raw}${end < body.length ? "…" : ""}`;
}

/* 大小写不敏感高亮命中词 */
function Highlight({ text, q }: { text: string; q: string }) {
  if (!q) return <>{text}</>;
  const lower = text.toLowerCase();
  const ql = q.toLowerCase();
  const parts: ReactNode[] = [];
  let i = 0;
  let key = 0;
  for (;;) {
    const hit = lower.indexOf(ql, i);
    if (hit === -1) {
      parts.push(text.slice(i));
      break;
    }
    if (hit > i) parts.push(text.slice(i, hit));
    parts.push(
      <mark key={key++} className="rounded-sm bg-accent/20 px-0.5 text-ink">
        {text.slice(hit, hit + ql.length)}
      </mark>
    );
    i = hit + ql.length;
  }
  return <>{parts}</>;
}

