/* ============ 小程序学习页：建档流的取消句柄与跨 tab toast ============
 * 事故链（pages/learn/learn.js create → generate）：
 *   reading-plan 生成 10-30s，旧实现 streamChat 没传 register。learn 是 tab 页，
 *   切 tab 只触发 onHide、不卸载页面，所以流不会被中止；但生成完成时弹的是
 *   **全局** toast——用户此时停在别的 tab 上，看不到「已建好阅读路线」，回来只见
 *   表单已关，容易再建一本同书名的重复书（createBookFromPlan 无同名去重）。
 * 修法：register 存取消句柄（onUnload 时取消）；结果 toast 只在本页可见时弹。
 * 书本身照常建好，回到本页 render 会列出来。
 *
 * 本测试真执行 learn.js（注入 require/wx/Page），流用 deferred 控制时序。 */

const requireCjs = createRequire(import.meta.url);
const ROOT = process.cwd();

type Dict = Record<string, unknown>;

let toasts: string[];
let streamOpts: any;
let created: any[];
let pageCfg: any;
let resolveStream: ((v: string) => void) | null;
let rejectStream: ((e: Error) => void) | null;
let streamShouldReject: boolean;

function loadLearn() {
  const utils = join(ROOT, "miniprogram/utils");
  const cache = requireCjs.cache as unknown as Record<string, unknown>;
  toasts = [];
  streamOpts = null;
  created = [];
  resolveStream = null;
  rejectStream = null;
  streamShouldReject = false;

  const store = {
    state: { userId: "u1", goals: [], books: [] },
    onLogin: () => Promise.resolve("pulled"),
    pullIfSafe: () => Promise.resolve("skip"),
    seedSampleGoal: () => {},
    createBookFromPlan: (...args: any[]) => {
      created.push(args);
      return "b1";
    },
  };
  cache[join(utils, "store.js")] = { id: "store", filename: "store", loaded: true, exports: store } as unknown;
  cache[join(utils, "api.js")] = {
    id: "api",
    filename: "api",
    loaded: true,
    exports: {
      hasSession: () => true,
      me: () => Promise.resolve({ user: { userId: "u1" } }),
      clearSession: () => {},
      // 可信书目来源 + 标题含书名（与 learn.js isCredibleSource/标题判据对齐）
      searchBooks: () =>
        Promise.resolve({
          results: [{ url: "https://book.douban.com/subject/1", title: "思考快与慢 书评" }],
        }),
    },
  } as unknown;
  cache[join(utils, "chat.js")] = {
    id: "chat",
    filename: "chat",
    loaded: true,
    exports: {
      streamChat: (o: any) => {
        streamOpts = o;
        return new Promise<string>((resolve, reject) => {
          resolveStream = resolve;
          rejectStream = reject;
        });
      },
      extractJson: (t: string) => JSON.parse(t),
    },
  } as unknown;

  const g = globalThis as unknown as Dict;
  g.wx = {
    getStorageSync: () => "",
    setStorageSync: () => {},
    removeStorageSync: () => {},
    showToast: (o: { title: string }) => toasts.push(o.title),
    showModal: () => {},
    reLaunch: () => {},
    navigateTo: () => {},
    stopPullDownRefresh: () => {},
  };

  const pagePath = join(ROOT, "miniprogram/pages/learn/learn.js");
  delete cache[pagePath];
  let captured: any = null;
  (globalThis as unknown as Dict).Page = (cfg: any) => {
    captured = cfg;
  };
  requireCjs(pagePath);
  if (!captured) throw new Error("learn.js 未调用 Page()");
  pageCfg = captured;
}

function makePage(): any {
  const page = Object.assign({}, pageCfg);
  page.data = JSON.parse(JSON.stringify(pageCfg.data));
  page.setData = function (patch: Dict) {
    Object.assign(this.data, patch);
  };
  return page;
}

const settle = async (n = 40) => {
  for (let i = 0; i < n; i++) await Promise.resolve();
};

/** 走到「生成流已在途」的状态（searchBooks 已核实通过） */
async function startCreate(page: any) {
  page.onShow();
  page.setData({ title: "思考快与慢" });
  page.create();
  await settle();
}

const OK_PLAN = JSON.stringify({ chapters: [{ title: "第一章" }] });

beforeEach(() => {
  loadLearn();
});

describe("mp-learn-create: 建档流的取消句柄 + toast 只在本页可见时弹", () => {
  it("streamChat 传入 register；页面可见时正常提示", async () => {
    const page = makePage();
    await startCreate(page);
    expect(streamOpts).toBeTruthy();
    expect(typeof streamOpts.register).toBe("function");

    resolveStream!(OK_PLAN);
    await settle();
    expect(created.length).toBe(1);
    expect(toasts).toContain("已建好阅读路线");
  });

  it("生成期间切走 tab（onHide）：书照常建好，但 toast 不弹在别的页面上", async () => {
    const page = makePage();
    await startCreate(page);
    page.onHide(); // 用户切到别的 tab
    resolveStream!(OK_PLAN);
    await settle();

    expect(created.length).toBe(1); // 书必须照常建好
    expect(toasts).not.toContain("已建好阅读路线");
  });

  it("页面销毁（onUnload）调用取消句柄；之后流结束也不再对死页 setData/toast", async () => {
    const page = makePage();
    await startCreate(page);
    let cancelled = false;
    streamOpts.register(() => {
      cancelled = true;
    });
    page.onUnload();
    expect(cancelled).toBe(true);

    // 流在取消后仍可能落地（cancel 与完成赛跑）：不得写死页
    resolveStream!(OK_PLAN);
    await settle();
    expect(toasts).not.toContain("已建好阅读路线");
  });

  it("失败路径同样只在可见时提示", async () => {
    const page = makePage();
    await startCreate(page);
    page.onHide();
    rejectStream!(new Error("生成失败"));
    await settle();
    expect(toasts).not.toContain("生成失败");
  });

  it("可见时失败要提示（守卫没有误伤正常失败反馈）", async () => {
    const page = makePage();
    await startCreate(page);
    rejectStream!(new Error("生成失败"));
    await settle();
    expect(toasts).toContain("生成失败");
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";
import { createRequire } from "node:module";
import { join } from "node:path";

/* ============ 小程序 store：本机缓存读不出必须可见，不能渲染成「还没有数据」 ============
 * 旧实现 loadLocal 的 catch 对 wx.getStorageSync 异常与 JSON.parse 失败一律静默
 * return false，不 emitStatus、不留痕。本机缓存正是未推送数据的唯一副本（260-263 行
 * 注释的设计目标就是靠它 + 脏标记跨进程救援）：缓存损坏（弱网/进程被杀导致半截写入）
 * 时救援链静默断裂——「云端为空 + 缓存损坏 + 脏标记残留」下页面呈现裸空态，与
 * 「从未产生数据」不可区分，用户看不到任何失败提示。
 * 修复：记录 localLoadFailed 并 emitStatus("error")；pullIfSafe 在「云端为空且本机
 * 也没有数据」时据此返回 "error"（而不是 "none"），页面 toast 与同步徽章都可见。 */

const requireCjs = createRequire(import.meta.url);
const ROOT = process.cwd();
const STORE_PATH = join(ROOT, "miniprogram/utils/store.js");
const API_PATH = join(ROOT, "miniprogram/utils/api.js");

let storage: Map<string, unknown>;
let statuses: string[];
let cloudToReturn: any;
let store: any;

function installWxStub() {
  storage = new Map();
  statuses = [];
  const g = globalThis as unknown as Record<string, unknown>;
  g.wx = {
    getStorageSync: (k: string) => (storage.has(k) ? storage.get(k) : ""),
    setStorageSync: (k: string, v: unknown) => void storage.set(k, v),
    removeStorageSync: (k: string) => void storage.delete(k),
    showToast: () => {},
  };
}

function loadStore() {
  for (const p of [STORE_PATH, API_PATH]) delete requireCjs.cache[p];
  const mod = requireCjs(STORE_PATH);
  const api = requireCjs(API_PATH);
  api.pushCloud = () => Promise.resolve({ updatedAt: "2026-01-01T00:00:00.000Z" });
  api.pullCloud = () => Promise.resolve(cloudToReturn);
  mod.onSyncStatus((s: string) => statuses.push(s));
  return mod;
}

const flush = async () => {
  for (let i = 0; i < 12; i++) await Promise.resolve();
};

beforeEach(() => {
  installWxStub();
  store = loadStore();
});

describe("mp-store 本机缓存损坏的可见性", () => {
  it("缓存 JSON 损坏 + 云端为空：pull 返回 error（不是 none），且同步状态转 error", async () => {
    storage.set("mentora-mp-store-u1", '{"goals":[{"id":"half'); // 半截写入
    cloudToReturn = null; // 云端没有快照

    const r = await store.onLogin("u1");
    await flush();

    expect(r).toBe("error"); // 旧实现这里回 "none"，页面渲染成空态
    expect(statuses).toContain("error");
  });

  it("缓存损坏但云端有数据：照常采用云端，并清掉错误状态", async () => {
    storage.set("mentora-mp-store-u1", "not-json");
    cloudToReturn = {
      data: { goals: [{ id: "cloud-goal" }], knowledge: [], books: [], sessions: [], customPersonas: [] },
      updatedAt: "2026-02-01T00:00:00.000Z",
    };

    const r = await store.onLogin("u1");
    await flush();

    expect(r).toBe("pulled");
    expect(store.state.goals.map((g: any) => g.id)).toEqual(["cloud-goal"]);
  });

  it("没有缓存（首次登录）不算失败：云端为空时返回 none", async () => {
    cloudToReturn = null;
    const r = await store.onLogin("u1");
    await flush();
    expect(r).toBe("none");
    expect(statuses).not.toContain("error");
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";
import { createRequire } from "node:module";
import { join } from "node:path";

/* ============ 小程序 store：pullIfSafe 必须做在途去重 ============
 * 旧实现只在成功回调里更新 lastPullAt，检查却发生在请求发出前：首次全量拉取
 * （MB 级、弱网下数秒）完成前，每次 tab onShow 都能穿过 30s 节流检查，各自发起
 * 一次全量快照请求——没有 in-flight 去重。影响是重复带宽/流量与服务端读放大。
 * 修复：pullInFlight 记录在途请求（带会话代数），同会话的在途拉取直接复用。
 * 本锁同时钉住：换账号后不能被上一账号的在途拉取顶替（否则新账号永远拿不到数据）。 */

const requireCjs = createRequire(import.meta.url);
const ROOT = process.cwd();
const STORE_PATH = join(ROOT, "miniprogram/utils/store.js");
const API_PATH = join(ROOT, "miniprogram/utils/api.js");

type Deferred<T> = { promise: Promise<T>; resolve: (v: T) => void };
function deferred<T>(): Deferred<T> {
  let resolve!: (v: T) => void;
  const promise = new Promise<T>((r) => {
    resolve = r;
  });
  return { promise, resolve };
}

let storage: Map<string, unknown>;
let pulls: Deferred<any>[];
let store: any;

function installWxStub() {
  storage = new Map();
  const g = globalThis as unknown as Record<string, unknown>;
  g.wx = {
    getStorageSync: (k: string) => (storage.has(k) ? storage.get(k) : ""),
    setStorageSync: (k: string, v: unknown) => void storage.set(k, v),
    removeStorageSync: (k: string) => void storage.delete(k),
    showToast: () => {},
  };
}

function loadStore() {
  for (const p of [STORE_PATH, API_PATH]) delete requireCjs.cache[p];
  const mod = requireCjs(STORE_PATH);
  const api = requireCjs(API_PATH);
  pulls = [];
  api.pushCloud = () => Promise.resolve({ updatedAt: "2026-01-01T00:00:00.000Z" });
  api.pullCloud = () => {
    const d = deferred<any>();
    pulls.push(d);
    return d.promise;
  };
  return mod;
}

const flush = async () => {
  for (let i = 0; i < 12; i++) await Promise.resolve();
};

beforeEach(() => {
  installWxStub();
  store = loadStore();
});

describe("mp-store pullIfSafe 在途去重", () => {
  it("首次拉取未完成时连续多次 onShow：只发一次全量请求，共用同一结果", async () => {
    const first = store.onLogin("u1");
    await flush();
    expect(pulls).toHaveLength(1); // onLogin 的 force 拉取已发出

    // 首拉仍在途：模拟两次 tab onShow 的 pullIfSafe(false)
    const second = store.pullIfSafe(false);
    const third = store.pullIfSafe(true);
    await flush();
    expect(pulls).toHaveLength(1); // 没有并发重拉

    pulls[0].resolve({
      data: { goals: [{ id: "cloud-goal" }], knowledge: [], books: [], sessions: [], customPersonas: [] },
      updatedAt: "2026-02-01T00:00:00.000Z",
    });
    await flush();

    await expect(first).resolves.toBe("pulled");
    await expect(second).resolves.toBe("pulled");
    await expect(third).resolves.toBe("pulled");
    expect(store.state.goals.map((g: any) => g.id)).toEqual(["cloud-goal"]);
    expect(pulls).toHaveLength(1);
  });

  it("首拉完成后 30s 内的非 force 调用照常 skip（节流语义不变）", async () => {
    const first = store.onLogin("u1");
    await flush();
    pulls[0].resolve({ data: null, updatedAt: "" });
    await first;
    await flush();

    await expect(store.pullIfSafe(false)).resolves.toBe("skip");
    expect(pulls).toHaveLength(1);
  });
});

